export async function validateAIRPBlock(node: BlockNode) {
  const schema = await registry.resolve(node.type);
  if (!schema) {
    throw new UnsupportedBlockError(node.type);
  }
  // Validate against the closed block catalog.
  return ajv.validate(schema, node.payload);
}

